{
  "name": "CI",
  "on": {
    "push": {
      "branches": [
        "main"
      ]
    },
    "pull_request": null
  },
  "permissions": {
    "contents": "read"
  },
  "env": {
    "NODE_OPTIONS": "--max-old-space-size=4096"
  },
  "jobs": {
    "lint": {
      "runs-on": "ubuntu-latest",
      "steps": [
        {
          "uses": "actions/checkout@v4"
        },
        {
          "uses": "actions/setup-node@v4",
          "with": {
            "node-version": 20,
            "cache": "npm"
          }
        },
        {
          "run": "npm ci"
        },
        {
          "run": "npm run lint"
        }
      ]
    },
    "test": {
      "needs": "lint",
      "runs-on": "${{ matrix.os }}",
      "strategy": {
        "fail-fast": false,
        "matrix": {
          "os": [
            "ubuntu-latest",
            "macos-latest"
          ],
          "node": [
            20,
            22
          ]
        }
      },
      "steps": [
        {
          "name": "Check out",
          "uses": "actions/checkout@v4",
          "with": {
            "fetch-depth": 0
          }
        },
        {
          "uses": "actions/setup-node@v4",
          "with": {
            "node-version": "${{ matrix.node }}"
          }
        },
        {
          "run": "npm ci"
        },
        {
          "run": "npm test -- --coverage",
          "env": {
            "CI": "true"
          }
        }
      ]
    }
  }
}
